from pathlib import Path
import hashlib,json,os,subprocess,sys,tarfile,time
W=Path(__file__).resolve().parents[1];S=W/'worktree';T=W/'temp';E=W/'evidence'
BASE='500020e7dc6d702ef059f0e73a4bab738103b774';ORIGIN='f43257225e1fd65c58ea8f5d7b220c3a509c203b';HARNESS='d24087eedd21c6384c231fb119c8e98da7b370aa'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def inv(p):return {str(f.relative_to(p)):sha(f) for f in sorted(p.rglob('*')) if f.is_file()}
def git(*args):return subprocess.check_output(['git',*args],cwd=S,text=True).strip()
def dump(p,x):p.write_text(json.dumps(x,indent=2)+'\n')
assert not git('status','--porcelain')
identities={k:json.loads(subprocess.check_output([sys.executable,'scripts/git_identity.py','inspect',v],cwd=S,text=True)) for k,v in {'baseline':BASE,'guest_origin':ORIGIN,'execution':git('rev-parse','HEAD'),'harness':HARNESS}.items()}
for k,v in identities.items():assert v['object_type']=='commit' and v['object_sha']==v['source_commit']
# Every product Go/SDK input is identical before installing the experimental guest.
changed=git('diff','--name-only',BASE,ORIGIN,'--','internal','python','*.go','go.mod','go.sum',':!benchmarks',':!tests',':!docs')
assert not changed,changed
plan=json.loads((S/'benchmarks/uca-copy-performance/plan.json').read_text());plan['resolved_sources']=identities;dump(E/'build-plan.json',plan)
env={k:v for k,v in os.environ.items() if not k.startswith(('GO','MARIAMEM_','MYSQLMEM_','GIT_'))}
env.update(GOCACHE=str(T/'gocache'),GOPATH=str(T/'gopath'),GOMODCACHE=str(T/'modcache'),GOTOOLCHAIN='go1.26.10',GOWORK='off',GOENV='off',GOFLAGS='',GOEXPERIMENT='',GOMAXPROCS='2',PYTHONDONTWRITEBYTECODE='1',TMPDIR=str(T/'scratch'),GOTMPDIR=str(T/'scratch'))
(T/'scratch').mkdir(exist_ok=True)
if '--reuse-installation' not in sys.argv:
 print('experimental installation start',flush=True)
 with (T/'installation.log').open('w') as log:
  subprocess.run([sys.executable,S/'tests/uca_copy_execution.py','--origin',T/'origin','--artifacts',T/'artifacts','--output',T/'execution'],cwd=S,env=env,stdout=log,stderr=subprocess.STDOUT,check=True,timeout=2400)
installed=json.loads((T/'execution/installation.json').read_text());ci=json.loads((T/'mac-installation.json').read_text())
assert installed['guest_sha256']==plan['candidate_guest_sha256']
assert installed['execution_source_commit']==identities['execution']['source_commit']
assert installed['generated_inventory']==inv(T/'execution/product/internal/generatedgo')
a=installed['generated_inventory'];b=ci['generated_inventory']
differences={k:{'local':a.get(k),'ci':b.get(k)} for k in sorted(set(a)|set(b)) if a.get(k)!=b.get(k)}
assert set(differences)<= {'provenance.json'},differences
provenance=json.loads((T/'execution/product/internal/generatedgo/provenance.json').read_text())
assert provenance['guest_sha256']==installed['guest_sha256']
assert provenance['dev_inputs_sha256']==provenance['input_manifest_sha256']==sha(T/'execution/installation-inputs.json')
assert provenance['contract']=='development-unqualified-v1' and provenance['result']=='UNQUALIFIED'
for name,digest in provenance['files_sha256'].items():assert a[name]==digest
assert sha(T/'execution/mariamem-uca-copy-host')==installed['host_sha256']==ci['host_sha256']
dump(E/'installation-metadata-difference.json',{'differences':differences,'runtime_files_match_mac_ci':True,'local_provenance_self_consistent':True,'explanation':'Only provenance.json differs: its input digest includes location-bound installation-inputs.json. All other generated files including code, data, layout and tests are exact Mac CI bytes. No runtime byte exception.'})
dump(E/'installation.json',{k:v for k,v in installed.items() if k!='generated_inventory'}|{'generated_inventory_sha256':hashlib.sha256(json.dumps(installed['generated_inventory'],sort_keys=True).encode()).hexdigest(),'runtime_files_match_mac_ci':True,'metadata_exception':'provenance.json; local input digest checked separately'})
print('installation PASS; all non-provenance generated bytes match Mac CI',flush=True)
(T/'candidate').symlink_to(T/'execution/product',target_is_directory=True)
A=T/'baseline';A.mkdir();archive=T/'baseline.tar'
with archive.open('wb') as f:subprocess.run(['git','archive',BASE],cwd=S,stdout=f,check=True)
with tarfile.open(archive) as tf:tf.extractall(A,filter='data')
archive.unlink()
for arm in ['baseline','candidate']:
 A=T/arm;before=inv(A/'internal/generatedgo');archive=T/'harness.tar'
 with archive.open('wb') as f:subprocess.run(['git','archive',HARNESS,'tests/timer_calibration/runner'],cwd=S,stdout=f,check=True)
 with tarfile.open(archive) as tf:tf.extractall(A,filter='data')
 archive.unlink();runner=A/'tests/timer_calibration/runner';binary=T/(arm+'.test');start=time.monotonic()
 print(arm,'runner compile start',flush=True)
 with (T/(arm+'-build.log')).open('w') as log:subprocess.run(['go','test','-mod=readonly','-p','1','-trimpath','-buildvcs=false','-c','-o',binary,'./maria/store'],cwd=runner,env=env,stdout=log,stderr=subprocess.STDOUT,check=True,timeout=1200)
 assert inv(A/'internal/generatedgo')==before
 buildinfo=subprocess.check_output(['go','version','-m',binary],env=env,text=True).replace(str(T),'<TEMP>')
 dump(E/(arm+'-runner.json'),{'source':identities['baseline' if arm=='baseline' else 'guest_origin'],'execution_source':identities['execution'],'harness_source':identities['harness'],'harness_files_sha256':inv(runner),'generated_inventory_sha256':hashlib.sha256(json.dumps(before,sort_keys=True).encode()).hexdigest(),'guest_sha256':installed['guest_sha256'] if arm=='candidate' else json.loads((A/'release/generated-go-build.json').read_text())['guest_sha256'],'binary_sha256':sha(binary),'binary_size_bytes':binary.stat().st_size,'generated_files_bytes':{str(p.relative_to(A/'internal/generatedgo')):p.stat().st_size for p in (A/'internal/generatedgo').rglob('*') if p.is_file() and p.suffix=='.bin'},'buildinfo':buildinfo,'compile_wall_seconds':time.monotonic()-start,'buildvcs':False,'source_attribution':'Exact source commit; identical injected harness; candidate isolated installation matches Mac CI full generated inventory; all non-guest product Go/SDK sources equal.'})
 print(arm,'runner build PASS',round(time.monotonic()-start,1),flush=True)
assert json.loads((E/'baseline-runner.json').read_text())['harness_files_sha256']==json.loads((E/'candidate-runner.json').read_text())['harness_files_sha256']
assert not git('status','--porcelain')
print('BUILD COMPLETE',flush=True)

for arm in ['baseline','candidate']:
 previous=json.loads((S/'benchmarks/uca-copy-performance'/(arm+'-runner.json')).read_text())
 assert sha(T/(arm+'.test'))==previous['binary_sha256'], 'observer-off runner differs from preceding measurement'
 runner=T/arm/'tests/timer_calibration/runner'
 subprocess.run([sys.executable,S/'benchmarks/uca-p8-attribution/reproduction/instrument.py',S,runner],check=True)
 print(arm,'diagnostic runner compile start',flush=True)
 with (T/(arm+'-diag-build.log')).open('w') as log:
  subprocess.run(['go','test','-mod=readonly','-p','1','-trimpath','-buildvcs=false','-c','-o',T/(arm+'.diag.test'),'./maria/store'],cwd=runner,env=env,stdout=log,stderr=subprocess.STDOUT,check=True,timeout=600)
 dump(E/(arm+'-diagnostic.json'),{'binary_sha256':sha(T/(arm+'.diag.test')),'injection':json.loads((runner/'diagnostic-injection.json').read_text())})
 print(arm,'diagnostic runner PASS',flush=True)
assert json.loads((E/'baseline-diagnostic.json').read_text())['injection']==json.loads((E/'candidate-diagnostic.json').read_text())['injection']
print('ALL BUILDS COMPLETE',flush=True)
